async function isUp(url, timeoutMs = 10000) {
    try {
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), timeoutMs);
        const resp = await fetch(url, {
            method: 'HEAD',
            signal: controller.signal,
        });
        clearTimeout(timer);
        return resp.ok;
    } catch {
        return false;
    }
}

