import (
    "net/http"
    "time"
)

func IsUp(url string) bool {
    client := &http.Client{Timeout: 10 * time.Second}
    resp, err := client.Head(url)
    if err != nil {
        return false
    }
    defer resp.Body.Close()
    return resp.StatusCode >= 200 && resp.StatusCode < 400
}

